#!/usr/bin/env node
/**
 * extract-teeth-svg.mjs
 * ---------------------
 * Extracts individual tooth SVG paths from the master "DIENTES ODONTOGRAMA.svg"
 * generated by Adobe Illustrator. Outputs a TypeScript data file with all paths
 * organized by tooth number, view (V/O/L/P), and zone (01-04).
 *
 * Usage: node scripts/extract-teeth-svg.mjs
 */

import { readFileSync, writeFileSync } from "fs";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const SVG_PATH = resolve(__dirname, "../public/DIENTES ODONTOGRAMA.svg");
const OUT_PATH = resolve(
  __dirname,
  "../components/features/odontogram/teeth-svg-data.ts"
);

// ── 1. Read SVG ──────────────────────────────────────────────────────────────
const svg = readFileSync(SVG_PATH, "utf-8");

// ── 2. Decode Illustrator XML-encoded IDs ────────────────────────────────────
//    _x33_8V  → 38V
//    _x31_1O-01 → 11O-01
function decodeId(raw) {
  let decoded = raw.replace(/_x([0-9a-fA-F]{2})_/g, (_, hex) =>
    String.fromCharCode(parseInt(hex, 16))
  );
  if (decoded.startsWith('_') && /^_[1-4][1-8]/.test(decoded)) {
    decoded = decoded.substring(1);
  }
  return decoded;
}

// ── 3. Extract all top-level <g id="..."> blocks ─────────────────────────────
//    We capture the outer <g> with its id and everything inside it.
//    Illustrator nests: <g id="XXX"> ... <path .../> ... </g>
function extractGroups(svgText) {
  const groups = {};
  const groupOrder = []; // track insertion order for adjacency

  // Match top-level groups with our tooth IDs (starting with _x3 or _[1-4])
  // AND Capa_XX groups (Illustrator layer names, may contain orphaned roots)
  const groupRegex =
    /<g\s+id="(_x3[^"]+|_[1-4][1-8][^"]*|Capa_\d+)"[^>]*>\s*([\s\S]*?)\s*<\/g>/g;

  let match;
  while ((match = groupRegex.exec(svgText)) !== null) {
    const rawId = match[1];
    const content = match[2];
    const decoded = decodeId(rawId);
    groups[decoded] = content;
    groupOrder.push(decoded);
  }

  return { groups, groupOrder };
}

// ── 4. Extract <path> d attributes from group content ────────────────────────
function extractPaths(content) {
  const paths = [];
  const pathRegex = /<path[^>]*\sd="([^"]+)"[^>]*\/?>/g;
  let m;
  while ((m = pathRegex.exec(content)) !== null) {
    paths.push(m[1]);
  }
  // Also extract polygons (some number labels use them)
  const polyRegex = /<polygon[^>]*\spoints="([^"]+)"[^>]*\/?>/g;
  while ((m = polyRegex.exec(content)) !== null) {
    // Convert polygon points to path d
    const pts = m[1].trim().split(/\s+/);
    if (pts.length >= 2) {
      const d = `M${pts[0]} L${pts.slice(1).join(" L")} Z`;
      paths.push(d);
    }
  }
  // Also extract <rect> → path. The designer drew the CENTRAL occlusal zone of
  // posterior teeth (and the central facial zone of anterior V views) as <rect>;
  // without this they were silently dropped, leaving the occlusal face
  // unpaintable. Attributes are read BY NAME (Illustrator order varies).
  const rectRegex = /<rect\b[^>]*?\/?>/g;
  while ((m = rectRegex.exec(content)) !== null) {
    const tag = m[0];
    const attr = (name) => {
      const a = tag.match(new RegExp(`\\s${name}="([^"]+)"`));
      return a ? parseFloat(a[1]) : NaN;
    };
    const x = attr("x");
    const y = attr("y");
    const w = attr("width");
    const h = attr("height");
    if ([x, y, w, h].every((n) => Number.isFinite(n))) {
      paths.push(`M${x},${y} H${x + w} V${y + h} H${x} Z`);
    }
  }
  return paths;
}

// ── 5. Calculate bounding box from path d string ─────────────────────────────
function pathBounds(d) {
  // Extract all numbers that represent coordinates
  const nums = [];
  const numRegex = /[-+]?[0-9]*\.?[0-9]+/g;
  let m;

  // We parse the path commands to extract coordinate pairs
  const commands = d.match(/[MLHVCSQTAZmlhvcsqtaz][^MLHVCSQTAZmlhvcsqtaz]*/g) || [];

  let curX = 0, curY = 0;
  const xs = [], ys = [];

  for (const cmd of commands) {
    const type = cmd[0];
    const args = [];
    let nm;
    const argRegex = /[-+]?[0-9]*\.?[0-9]+/g;
    while ((nm = argRegex.exec(cmd.slice(1))) !== null) {
      args.push(parseFloat(nm[0]));
    }

    switch (type) {
      case "M":
      case "L":
        for (let i = 0; i < args.length - 1; i += 2) {
          curX = args[i]; curY = args[i + 1];
          xs.push(curX); ys.push(curY);
        }
        break;
      case "m":
        for (let i = 0; i < args.length - 1; i += 2) {
          curX += args[i]; curY += args[i + 1];
          xs.push(curX); ys.push(curY);
        }
        break;
      case "l":
        for (let i = 0; i < args.length - 1; i += 2) {
          curX += args[i]; curY += args[i + 1];
          xs.push(curX); ys.push(curY);
        }
        break;
      case "H":
        for (const a of args) { curX = a; xs.push(curX); ys.push(curY); }
        break;
      case "h":
        for (const a of args) { curX += a; xs.push(curX); ys.push(curY); }
        break;
      case "V":
        for (const a of args) { curY = a; xs.push(curX); ys.push(curY); }
        break;
      case "v":
        for (const a of args) { curY += a; xs.push(curX); ys.push(curY); }
        break;
      case "C":
        for (let i = 0; i < args.length - 1; i += 2) {
          xs.push(args[i]); ys.push(args[i + 1]);
        }
        if (args.length >= 6) {
          curX = args[args.length - 2]; curY = args[args.length - 1];
        }
        break;
      case "c":
        for (let i = 0; i < args.length - 1; i += 6) {
          xs.push(curX + args[i], curX + args[i + 2], curX + args[i + 4]);
          ys.push(curY + args[i + 1], curY + args[i + 3], curY + args[i + 5]);
          if (i + 5 < args.length) {
            curX += args[i + 4]; curY += args[i + 5];
          }
        }
        break;
      case "Q":
        for (let i = 0; i < args.length - 1; i += 2) {
          xs.push(args[i]); ys.push(args[i + 1]);
        }
        if (args.length >= 4) {
          curX = args[args.length - 2]; curY = args[args.length - 1];
        }
        break;
      case "q":
        for (let i = 0; i < args.length - 1; i += 4) {
          xs.push(curX + args[i], curX + args[i + 2]);
          ys.push(curY + args[i + 1], curY + args[i + 3]);
          curX += args[i + 2]; curY += args[i + 3];
        }
        break;
      case "S":
      case "s":
        // Similar to C/c but with implied first control point
        for (let i = 0; i < args.length - 1; i += 2) {
          const ax = type === "s" ? curX + args[i] : args[i];
          const ay = type === "s" ? curY + args[i + 1] : args[i + 1];
          xs.push(ax); ys.push(ay);
        }
        if (args.length >= 4) {
          curX = type === "s" ? curX + args[args.length - 2] : args[args.length - 2];
          curY = type === "s" ? curY + args[args.length - 1] : args[args.length - 1];
        }
        break;
      case "Z":
      case "z":
        break;
      default:
        // For A/a and other commands, just extract numbers as rough bounds
        for (let i = 0; i < args.length - 1; i += 2) {
          xs.push(args[i]); ys.push(args[i + 1]);
        }
        break;
    }
  }

  if (xs.length === 0 || ys.length === 0) return null;

  return {
    minX: Math.min(...xs),
    minY: Math.min(...ys),
    maxX: Math.max(...xs),
    maxY: Math.max(...ys),
  };
}

function combineBounds(boundsArr) {
  const valid = boundsArr.filter(Boolean);
  if (valid.length === 0) return { minX: 0, minY: 0, maxX: 100, maxY: 100 };
  return {
    minX: Math.min(...valid.map((b) => b.minX)),
    minY: Math.min(...valid.map((b) => b.minY)),
    maxX: Math.max(...valid.map((b) => b.maxX)),
    maxY: Math.max(...valid.map((b) => b.maxY)),
  };
}

// ── 5b. Clasificador GEOMÉTRICO zona → superficie dental ──────────────────────
// El número de zona del SVG es orden de dibujo de Illustrator, NO anatomía
// (verificado: el mismo número significa caras distintas según diente/cuadrante).
// Por eso clasificamos cada zona por la POSICIÓN de su centroide dentro del
// viewBox, no por su id. FDI/ISO 3950: mesial apunta a la línea media (su lado
// físico depende del cuadrante); el borde incisal/oclusal queda abajo en
// maxilares y arriba en mandibulares; la cara interna es palatina (maxilar) o
// lingual (mandibular). 'incisal' se codifica como 'oclusal' en el enum del render.
function classifyView(zones, viewBounds, fdi, viewCategory) {
  const q = parseInt(fdi[0], 10);
  const maxillary = q === 1 || q === 2;
  const mesialOnRight = q === 1 || q === 4; // hacia la línea media del lienzo
  const position = parseInt(fdi[1], 10);
  const anterior = position >= 1 && position <= 3;
  const w = viewBounds.maxX - viewBounds.minX || 1;
  const h = viewBounds.maxY - viewBounds.minY || 1;
  const proximalLeft = mesialOnRight ? "distal" : "mesial";
  const proximalRight = mesialOnRight ? "mesial" : "distal";

  const entries = Object.entries(zones).map(([z, paths]) => {
    const b = combineBounds(paths.map(pathBounds));
    return {
      z,
      cx: b ? ((b.minX + b.maxX) / 2 - viewBounds.minX) / w : 0.5,
      cy: b ? ((b.minY + b.maxY) / 2 - viewBounds.minY) / h : 0.5,
      // Área del bbox: discrimina cervical (grande) vs filo/cuerpo (pequeño) en
      // la vista lateral, donde el arte invertido hace poco fiable el cy.
      area: b ? (b.maxX - b.minX) * (b.maxY - b.minY) : 0,
    };
  });

  const result = {};
  const centers = [];
  for (const e of entries) {
    if (e.cx < 0.35) result[e.z] = proximalLeft;
    else if (e.cx > 0.65) result[e.z] = proximalRight;
    else centers.push(e);
  }

  if (viewCategory === "occlusal") {
    // Vista oclusal (top-down): banda superior/inferior = bucal/lingual según
    // arcada; la central (mesa oclusal, rect) = oclusal. NUNCA emite 'cervical':
    // el tercio cervical queda ocluido mirando por el eje largo (G.V. Black V).
    for (const e of centers) {
      if (e.cy < 0.35) result[e.z] = maxillary ? "facial" : "lingual";
      else if (e.cy > 0.65) result[e.z] = maxillary ? "lingual" : "facial";
      else result[e.z] = "oclusal";
    }
  } else if (viewCategory === "vestibular") {
    // Vestibular: SOLO en ANTERIORES la zona del EXTREMO (maxilar=abajo/máx cy,
    // mandibular=arriba/mín cy) es el filo incisal ('oclusal'); en posteriores no
    // hay filo (la mesa oclusal va en la vista O).
    //
    // NORMA DE ETIQUETADO (confirmada por el dueño sobre el arte real del 28,
    // mirando cada zona coloreada): la BANDA de cuerpo MÁS GRANDE es el tercio
    // 'cervicalVestibular' (Clase V bucal — la zona dominante hacia el margen
    // gingival en este arte); la zona de cuerpo MENOR es la cara bucal marcable
    // ('facial' = Vestibular). Con un solo cuerpo (26/27) esa zona es 'facial'
    // (sin cervical separable).
    let edge = null;
    for (const e of centers) {
      if (!edge || (maxillary ? e.cy > edge.cy : e.cy < edge.cy)) edge = e;
    }
    const edgeIsReal =
      anterior && edge && (maxillary ? edge.cy > 0.6 : edge.cy < 0.4);
    const body = centers.filter((e) => !(edgeIsReal && e === edge));
    let cervical = null;
    if (body.length >= 2) {
      for (const e of body) {
        if (!cervical || e.area > cervical.area) cervical = e;
      }
    }
    for (const e of centers) {
      if (edgeIsReal && e === edge) result[e.z] = "oclusal";
      else if (e === cervical) result[e.z] = "cervicalVestibular";
      else result[e.z] = "facial";
    }
  } else {
    // Lateral (Palatino/Lingual): el arte se dibuja invertido respecto a su
    // vestibular (el adapter aplica un volteo vertical al render). Misma norma:
    // la BANDA central MÁS GRANDE es el tercio 'cervicalLingual'; la otra central
    // es la cara palatina/lingual ('lingual') en posteriores o el filo incisal
    // ('oclusal') en anteriores. Con una sola central se conserva 'lingual'.
    if (centers.length >= 2) {
      let cervical = centers[0];
      for (const e of centers) if (e.area > cervical.area) cervical = e;
      for (const e of centers) {
        result[e.z] =
          e === cervical ? "cervicalLingual" : anterior ? "oclusal" : "lingual";
      }
    } else {
      for (const e of centers) result[e.z] = "lingual";
    }
  }

  return result;
}

// ── 6. Main extraction ──────────────────────────────────────────────────────
const { groups, groupOrder } = extractGroups(svg);

// Build adjacency map: for each {fdi}V group, find the Capa_XX group right after it.
// This handles cases where the designer put the root in a generic Capa_XX layer
// instead of a properly named {fdi}V-ROOT group (e.g., tooth 13's root is in Capa_96).
const orphanRootMap = {};
for (let i = 0; i < groupOrder.length - 1; i++) {
  const current = groupOrder[i];
  const next = groupOrder[i + 1];
  // If current is a V outline (e.g., "13V") and next is a Capa_XX
  if (/^\d{2}V$/.test(current) && /^Capa_\d+$/.test(next)) {
    // Verify this tooth doesn't already have a ROOT group
    const hasExplicitRoot = groups[`${current}-ROOT`] || groups[`${current}-root`];
    if (!hasExplicitRoot) {
      orphanRootMap[current] = next;
    }
  }
}

// Organize by tooth number
const FDI_NUMBERS = [];
for (let q = 1; q <= 4; q++) {
  for (let p = 1; p <= 8; p++) {
    FDI_NUMBERS.push(`${q}${p}`);
  }
}

const VIEW_MAP = { V: "vestibular", O: "occlusal", L: "lingual", P: "palatinal" };
const VIEWS = ["V", "O", "L", "P"];

const registry = {};
let totalExtracted = 0;
let missingParts = [];

for (const fdi of FDI_NUMBERS) {
  registry[fdi] = {};

  for (const view of VIEWS) {
    const key = `${fdi}${view}`;

    // Check if this tooth/view combination exists
    // Zone paths (-01 to -05)
    const zones = {};
    let hasZones = false;
    for (const z of ["01", "02", "03", "04", "05"]) {
      const zoneKey = `${key}-${z}`;
      if (groups[zoneKey]) {
        const paths = extractPaths(groups[zoneKey]);
        if (paths.length > 0) {
          zones[z] = paths;
          hasZones = true;
        }
      }
    }

    // Outline path (the main group without suffix)
    let outline = null;
    if (groups[key]) {
      const paths = extractPaths(groups[key]);
      if (paths.length > 0) {
        outline = paths;
      }
    }

    // Root path (only for V view)
    // Note: some teeth use lowercase 'root' (e.g., 22V-root vs 22V-ROOT)
    let root = null;
    for (const rootSuffix of ["ROOT", "root"]) {
      const rootKey = `${key}-${rootSuffix}`;
      if (groups[rootKey]) {
        const paths = extractPaths(groups[rootKey]);
        if (paths.length > 0) {
          root = paths;
          break;
        }
      }
    }

    // Fallback: check if there's an orphaned Capa_XX group that contains
    // the root (e.g., tooth 13 has root in Capa_96 instead of _x31_3V-ROOT)
    if (!root && view === "V" && orphanRootMap[key]) {
      const capaKey = orphanRootMap[key];
      const paths = extractPaths(groups[capaKey]);
      if (paths.length > 0) {
        root = paths;
        console.log(`  ⚠ Found orphaned root for ${key} in ${capaKey}`);
      }
    }

    // Also check for alternative zone naming (some teeth have -011, -012, etc.)
    for (const altKey of Object.keys(groups)) {
      const decoded = altKey;
      if (decoded.startsWith(key + "-") && !decoded.toUpperCase().endsWith("-ROOT")) {
        const suffix = decoded.slice(key.length + 1);
        if (suffix.length > 2 && !zones[suffix]) {
          const paths = extractPaths(groups[decoded]);
          if (paths.length > 0) {
            zones[suffix] = paths;
            hasZones = true;
          }
        }
      }
    }

    if (hasZones || outline || root) {
      // Calculate combined bounding box for all paths in this view
      const allPaths = [
        ...(outline || []),
        ...Object.values(zones).flat(),
        ...(root || []),
      ];
      const bounds = combineBounds(allPaths.map(pathBounds));
      const padding = 2;
      const vbX = Math.floor(bounds.minX - padding);
      const vbY = Math.floor(bounds.minY - padding);
      const vbW = Math.ceil(bounds.maxX - bounds.minX + padding * 2);
      const vbH = Math.ceil(bounds.maxY - bounds.minY + padding * 2);

      // Clasifica las zonas por geometría (centroide relativo) → superficie dental.
      const viewCategory =
        view === "V" ? "vestibular" : view === "O" ? "occlusal" : "lateral";
      const zoneSurfaces = classifyView(zones, bounds, fdi, viewCategory);

      // Validación de coherencia: detecta arte degenerado (zonas duplicadas o
      // vistas oclusales posteriores sin las caras bucal/lingual). Avisa ruidoso
      // para revisar el SVG fuente en vez de generar datos clínicos corruptos.
      const surfVals = Object.values(zoneSurfaces);
      const seen = new Set();
      const dups = [];
      for (const s of surfVals) {
        // facial/lingual pueden venir de 2 zonas (cuerpo + cervical) → no es dup.
        if (s === "facial" || s === "lingual") continue;
        if (seen.has(s)) dups.push(s);
        seen.add(s);
      }
      if (dups.length) {
        console.warn(
          `  ⚠ ${fdi}${view}: superficies duplicadas [${dups.join(", ")}] → ${JSON.stringify(zoneSurfaces)} (revisar arte)`,
        );
      }
      const pos = parseInt(fdi[1], 10);
      if (
        viewCategory === "occlusal" &&
        pos >= 4 &&
        (!surfVals.includes("facial") || !surfVals.includes("lingual"))
      ) {
        console.warn(
          `  ⚠ ${fdi}${view}: oclusal posterior sin facial/lingual → ${JSON.stringify(zoneSurfaces)} (revisar arte)`,
        );
      }

      // Ancla del símbolo = centro de la CORONA (bbox de las zonas, sin raíz),
      // para que la letra/ícono no caiga sobre la raíz en la vista vestibular.
      const crownPaths = Object.values(zones).flat();
      const crownBounds = crownPaths.length
        ? combineBounds(crownPaths.map(pathBounds))
        : combineBounds((outline || []).map(pathBounds));
      const symbolAnchor = {
        x: Math.round(((crownBounds.minX + crownBounds.maxX) / 2) * 100) / 100,
        y: Math.round(((crownBounds.minY + crownBounds.maxY) / 2) * 100) / 100,
      };

      // Ancla de la RAÍZ = centroide del bbox de los paths de la raíz. Solo
      // existe cuando hay root (vista vestibular/frontal). Lo usa el render para
      // colocar símbolos "cerca de la raíz" (p.ej. el círculo de corona), que no
      // deben caer sobre la corona como el symbolAnchor.
      let rootAnchor = null;
      if (root && root.length) {
        const rootBounds = combineBounds(root.map(pathBounds));
        rootAnchor = {
          x: Math.round(((rootBounds.minX + rootBounds.maxX) / 2) * 100) / 100,
          y: Math.round(((rootBounds.minY + rootBounds.maxY) / 2) * 100) / 100,
        };
      }

      registry[fdi][view] = {
        outline: outline || [],
        zones,
        zoneSurfaces,
        symbolAnchor,
        rootAnchor,
        root: root || null,
        viewBox: `${vbX} ${vbY} ${vbW} ${vbH}`,
      };
      totalExtracted++;
    } else {
      missingParts.push(key);
    }
  }

  // Clean empty views
  for (const view of VIEWS) {
    if (!registry[fdi][view]) delete registry[fdi][view];
  }
  if (Object.keys(registry[fdi]).length === 0) {
    delete registry[fdi];
  }
}

console.log(`Total tooth/view combos extracted: ${totalExtracted}`);
console.log(`Missing: ${missingParts.length} (expected for L/P alternation)`);

// ── 7. Generate TypeScript output ────────────────────────────────────────────
let ts = `// AUTO-GENERATED by scripts/extract-teeth-svg.mjs
// Do not edit manually. Re-run the script to regenerate.
// Source: public/DIENTES ODONTOGRAMA.svg

export type ToothView = "V" | "O" | "L" | "P";
export type ToothZone = string; // "01" | "02" | "03" | "04" | "05" or extended

export interface ToothViewData {
  /** SVG paths for the complete outline/contour of the tooth in this view */
  outline: string[];
  /** SVG paths for each interactive zone (typically 4-5 zones per view) */
  zones: Record<string, string[]>;
  /**
   * Surface assigned to each zone by geometric classification (centroid-based,
   * not by zone id which is just Illustrator draw order). Values:
   * "oclusal" | "facial" | "lingual" | "mesial" | "distal".
   */
  zoneSurfaces: Record<string, string>;
  /** Center of the CROWN (zones bbox, excludes root) — anchor for the symbol. */
  symbolAnchor: { x: number; y: number };
  /**
   * Center of the ROOT (root paths bbox) — anchor for symbols drawn near the
   * root (e.g. the crown circle). Only present when the view has a root
   * (vestibular/frontal); null otherwise.
   */
  rootAnchor: { x: number; y: number } | null;
  /** SVG paths for the root (only in vestibular view) */
  root: string[] | null;
  /** Calculated viewBox for this tooth in this view */
  viewBox: string;
}

export type ToothSvgEntry = Partial<Record<ToothView, ToothViewData>>;

/**
 * Registry of all 32 permanent teeth with their SVG paths.
 * Keys are FDI tooth numbers (11-18, 21-28, 31-38, 41-48).
 * Each tooth has up to 3 views: V (vestibular), O (occlusal), L/P (lingual/palatinal).
 */
export const TOOTH_SVG_REGISTRY: Record<string, ToothSvgEntry> = {\n`;

for (const [fdi, views] of Object.entries(registry)) {
  ts += `  "${fdi}": {\n`;
  for (const [view, data] of Object.entries(views)) {
    ts += `    ${view}: {\n`;

    // Outline
    ts += `      outline: [\n`;
    for (const p of data.outline) {
      ts += `        ${JSON.stringify(p)},\n`;
    }
    ts += `      ],\n`;

    // Zones
    ts += `      zones: {\n`;
    for (const [z, paths] of Object.entries(data.zones)) {
      ts += `        "${z}": [\n`;
      for (const p of paths) {
        ts += `          ${JSON.stringify(p)},\n`;
      }
      ts += `        ],\n`;
    }
    ts += `      },\n`;

    // Zone → surface (geometric classification)
    ts += `      zoneSurfaces: ${JSON.stringify(data.zoneSurfaces || {})},\n`;

    // Symbol anchor (crown center)
    ts += `      symbolAnchor: ${JSON.stringify(data.symbolAnchor || { x: 0, y: 0 })},\n`;

    // Root anchor (root center) — null when the view has no root
    ts += `      rootAnchor: ${JSON.stringify(data.rootAnchor ?? null)},\n`;

    // Root
    if (data.root) {
      ts += `      root: [\n`;
      for (const p of data.root) {
        ts += `        ${JSON.stringify(p)},\n`;
      }
      ts += `      ],\n`;
    } else {
      ts += `      root: null,\n`;
    }

    // ViewBox
    ts += `      viewBox: ${JSON.stringify(data.viewBox)},\n`;
    ts += `    },\n`;
  }
  ts += `  },\n`;
}

ts += `};\n\n`;

// Add helper function
ts += `/**
 * Get the appropriate lateral view key for a tooth.
 * Superior teeth (Q1, Q2) use P (palatinal), inferior (Q3, Q4) use L (lingual).
 */
export function getLateralViewKey(fdiNumber: string): "L" | "P" {
  const quadrant = fdiNumber[0];
  return quadrant === "1" || quadrant === "2" ? "P" : "L";
}

/**
 * Get the view data for a tooth, handling the L/P mapping.
 * @param view - "vestibular" | "occlusal" | "lateral"
 */
export function getToothView(
  fdiNumber: string,
  view: "vestibular" | "occlusal" | "lateral"
): ToothViewData | undefined {
  const tooth = TOOTH_SVG_REGISTRY[fdiNumber];
  if (!tooth) return undefined;

  switch (view) {
    case "vestibular":
      return tooth.V;
    case "occlusal":
      return tooth.O;
    case "lateral":
      return tooth[getLateralViewKey(fdiNumber)];
  }
}

/**
 * List of all available tooth numbers in the registry.
 */
export const AVAILABLE_TEETH = Object.keys(TOOTH_SVG_REGISTRY);
`;

writeFileSync(OUT_PATH, ts, "utf-8");
console.log(`\n✅ Generated: ${OUT_PATH}`);
console.log(`   Teeth: ${Object.keys(registry).length}`);
console.log(`   Total views: ${totalExtracted}`);

// Print summary per quadrant
for (let q = 1; q <= 4; q++) {
  const teeth = FDI_NUMBERS.filter((f) => f[0] === String(q));
  const found = teeth.filter((f) => registry[f]);
  const views = found.map((f) =>
    Object.keys(registry[f])
      .map((v) => `${f}${v}`)
      .join(",")
  );
  console.log(`   Q${q}: ${found.length}/8 teeth → ${views.join(" | ")}`);
}
